tool_input.command:
$dir = Join-Path $env:TEMP 'zentao-6957'
$resolved = (Resolve-Path $dir -ErrorAction SilentlyContinue).Path
$tempRoot = (Resolve-Path $env:TEMP).Path
echo "TARGET=$resolved"
echo "TEMP_ROOT=$tempRoot"
if ($resolved -and $resolved.StartsWith($tempRoot) -and $resolved -like '*zentao-6957') {
  echo "=== contents before delete ==="
  Get-ChildItem -LiteralPath $resolved | Select-Object Name,Length
  Remove-Item -LiteralPath $resolved -Recurse -Force
  echo "DELETED=$(-not (Test-Path $resolved))"
} else {
  echo "SAFETY_ABORT: path check failed"
}
